struct BlackScholesInputs {
  double spot, strike, rate,
         vol, timeToExpiry;
};

inline double blackScholesCall(
    const BlackScholesInputs& in) {
  double sqrtT =
    std::sqrt(in.timeToExpiry);
  double d1 = (...) / (in.vol*sqrtT);
  double d2 = d1 - in.vol*sqrtT;
  return in.spot*normCdf(d1) -
    in.strike*std::exp(-in.rate*
    in.timeToExpiry)*normCdf(d2);
}

